async function initUsEtfPage() {
  const root = document.getElementById("us-etf-root");
  if (!root) return;
  root.innerHTML = `
    <section class="subpage-hero">
      <p class="eyebrow">US ETF Center</p>
      <h1>美股ETF資料載入中</h1>
      <p class="hero-text">正在取得美股 ETF 行情、分類與線上資料明細...</p>
    </section>
  `;
  try {
    const response = await fetchWithTimeout("/api/us-market/etf-center?directoryLimit=7000&quoteLimit=56", { cache: "no-store" }, 120000);
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const payload = await response.json();
    renderUsEtfPage(payload);
  } catch (error) {
    renderUsEtfPage({
      category: "us-etf",
      title: "美股ETF",
      source: "Nasdaq Trader 官方 Symbol Directory / Yahoo Finance 美股 ETF 行情",
      updatedAt: "--",
      items: [],
      error: error.message || String(error),
    });
    const note = document.querySelector("#us-etf-root .source-note");
    if (note) note.textContent = `美股 ETF 行情暫時無法載入，但美股 ETF 明細仍會嘗試同步。錯誤：${error.message || error}`;
  }
}

function getUsSectorStockSelectionStore(selectors = []) {
  const raw = sessionStorage.getItem(US_SECTOR_STOCK_SELECTION_KEY) || "";
  if (!raw) return { benchmark: "", sector: "" };
  try {
    const parsed = JSON.parse(raw);
    if (parsed && typeof parsed === "object") {
      return {
        benchmark: parsed.benchmark || "",
        sector: parsed.sector || "",
      };
    }
  } catch (error) {
    // Backward compatible with the earlier single-symbol storage.
  }
  const legacy = selectors.find((item) => item.symbol === raw);
  return legacy?.group === "主要指數"
    ? { benchmark: raw, sector: "" }
    : { benchmark: "", sector: raw };
}

function saveUsSectorStockSelection() {
  sessionStorage.setItem(US_SECTOR_STOCK_SELECTION_KEY, JSON.stringify({
    benchmark: usSectorStockBenchmarkSymbol || "",
    sector: usSectorStockSymbol || "",
  }));
}

function getUsSectorStockLabel(item) {
  if (!item) return "";
  return item.group === "主要指數" ? getUsBenchmarkDisplayName(item) : getUsSectorDisplayName(item);
}

