  const symbolText = sector
    ? `${benchmark?.symbol || "--"} / ${sector?.symbol || "--"}`
    : benchmark?.symbol || "--";
  const note = sector
    ? `${benchmarkLabel} 作為大盤基準，${sectorLabel} 作為目前類股觀察。`
    : `${benchmarkLabel} 作為目前大盤基準。`;
